func:
var p = msg.payload || {};
if (msg.topic === 'zigbee2mqtt/Chambre') {
    global.set('temp_chambre', p.temperature);
    global.set('hum_chambre', p.humidity);
}

// Nom du capteur deduit du topic MQTT : l'arrivee d'un 2e capteur ne
// demandera aucune modification ici.
var capteur = (msg.topic || '').split('/').pop() || 'inconnu';

// Le wildcard 'zigbee2mqtt/+' capte aussi les topics techniques du bridge.
if (capteur === 'bridge' || capteur === 'inconnu') return null;
var aTemp = typeof p.temperature === 'number';
var aLinky = capteur === 'Linky' && typeof p.apparent_power === 'number';
var tsLinky = aLinky ? (Date.parse(p.last_seen) || Date.now()) : null;

// Un format par consommateur, pour qu'un changement d'un cote n'en casse pas un autre.
return [
    { payload: p, capteur: capteur },                                   // 1. carte (routee par capteur)
    aTemp ? { payload: p.temperature } : null,                          // 2. seuil 30 C (nombre)
    aTemp ? { payload: p, capteur: capteur } : null,                    // 3. SQLite
    aTemp ? { payload: { ts: Date.parse(p.last_seen) || Date.now(),     // 4. graphe (point x/y/serie)
                         temp: p.temperature, capteur: capteur } } : null,
    aLinky ? { payload: p } : null,                                     // 5. SQLite Linky
    aLinky ? { payload: { ts: tsLinky, papp: p.apparent_power } } : null // 6. graphe Linky 24h (point)
];

var temp = msg.payload;
if (typeof temp !== 'number') return null;
var was = flow.get('over30') || false;
if (temp > 30 && !was) {
    flow.set('over30', true);
    msg.payload = 'Chambre: ' + temp + ' C (seuil 30 C depasse)';
    msg.headers = { 'Title': 'Alerte temperature', 'Priority': 'high', 'Tags': 'warning,thermometer' };
    return msg;
} else if (temp <= 30 && was) {
    flow.set('over30', false);
}
return null;

var t = global.get('temp_chambre');
var h = global.get('hum_chambre');
if (t === undefined || t === null) {
    msg.payload = "Je n'ai pas encore de mesure pour la chambre.";
} else {
    msg.payload = 'Il fait ' + t + ' degrés dans la chambre';
    if (h !== undefined && h !== null) { msg.payload += ', avec ' + Math.round(h) + ' pour cent d\'humidité.'; }
    else { msg.payload += '.'; }
}
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
return msg;

msg.method = "GET";
msg.url = "https://" + env.get("HUE_BRIDGE") + "/clip/v2/resource";
msg.headers = { "hue-application-key": env.get("HUE_KEY") };
return msg;

const norm = s => (s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]/g,"");
const data = ((msg.payload || {}).data) || [];
const by = t => data.filter(o => o.type === t);
const devices = {}; by("device").forEach(d => { devices[d.id] = d; });
const lights = {};  by("light").forEach(l => { lights[l.id] = l; });
const rooms = [];
by("room").concat(by("zone")).forEach(r => {
    const gl = (r.services || []).find(s => s.rtype === "grouped_light");
    const lids = [];
    (r.children || []).forEach(c => {
        const d = devices[c.rid];
        if (d) (d.services || []).forEach(s => { if (s.rtype === "light") lids.push(s.rid); });
        if (lights[c.rid]) lids.push(c.rid);
    });
    const nm = (r.metadata || {}).name || "?";
    rooms.push({ name: nm, norm: norm(nm), id: r.id, gl: gl ? gl.rid : null, lights: lids });
});
const scenes = by("scene").map(s => {
    const nm = (s.metadata || {}).name || "?";
    return { name: nm, norm: norm(nm), id: s.id, room: s.group.rid };
});
global.set("hue", { rooms: rooms, scenes: scenes, nbLights: Object.keys(lights).length, ts: Date.now() });
node.status({ fill: "green", shape: "dot", text: rooms.length + " pièces / " + scenes.length + " scènes" });
return null;

if (!global.get("hue")) {
    msg.statusCode = 503;
    msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
    msg.payload = "Inventaire Hue pas encore chargé, réessaie dans quelques secondes.";
    return [null, msg];
}
msg.method = "GET";
msg.headers = { "hue-application-key": env.get("HUE_KEY") };
msg.url = "https://" + env.get("HUE_BRIDGE") + "/clip/v2/resource/grouped_light";
return [msg, null];

const inv = global.get("hue") || { rooms: [] };
const glAll = {};
(((msg.payload || {}).data) || []).forEach(g => { glAll[g.id] = g; });
const pct = g => Math.round(((g.dimming || {}).brightness) || 0);
const parts = inv.rooms.map(r => {
    const g = glAll[r.gl];
    if (!g) return r.name + " : état inconnu";
    return g.on.on ? r.name + " allumé à " + pct(g) + " pour cent" : r.name + " éteint";
});
msg.statusCode = 200;
msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
msg.payload = parts.length ? parts.join(", ") + "." : "Aucune pièce Hue trouvée.";
return msg;

if (!msg.req) { node.warn("Hue (hors requête HTTP) : " + ((msg.error || {}).message || "erreur")); return null; }
msg.statusCode = 502;
msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
msg.payload = "Le pont Hue ne répond pas (" + ((msg.error || {}).message || "erreur inconnue") + ").";
return msg;

const db = context.get('db');
if (!db) { node.error('base SQLite non ouverte'); return null; }

const p = msg.payload || {};
const capteur = msg.capteur || 'inconnu';

// Sans temperature il n'y a rien a historiser (message d'etat, disponibilite...).
if (typeof p.temperature !== 'number') return null;

// On horodate avec la date du CAPTEUR (last_seen fourni par Z2M), pas l'heure
// de reception : sinon chaque reconnexion MQTT rejoue le message retained et
// fabrique une fausse mesure. Avec last_seen, la cle primaire (ts, capteur)
// rend l'insertion vraiment idempotente.
let ts = Date.parse(p.last_seen);
if (!Number.isFinite(ts)) {
    ts = Date.now();                       // repli si last_seen absent
    node.warn('last_seen absent pour ' + capteur + ', horodatage a la reception');
}

// Z2M publie plusieurs messages en rafale (un par attribut Zigbee recu), chacun
// avec un last_seen different a la milliseconde : la cle (ts, capteur) ne les
// deduplique donc pas. On ignore une mesure identique a la precedente si elle
// date de moins d'une minute — on ne perd rien, seul un changement compte.
const hum = typeof p.humidity === 'number' ? p.humidity : null;
const precedente = db.prepare(
    'SELECT temp, hum FROM mesures WHERE capteur = ? AND ts >= ? ORDER BY ts DESC LIMIT 1'
).get(capteur, ts - 60000);
if (precedente && precedente.temp === p.temperature && precedente.hum === hum) {
    return null;
}

try {
    db.prepare(
        'INSERT OR REPLACE INTO mesures (ts, capteur, temp, hum, batterie) VALUES (?, ?, ?, ?, ?)'
    ).run(
        ts,
        capteur,
        p.temperature,
        hum,
        typeof p.battery === 'number' ? Math.round(p.battery) : null
    );
    const n = db.prepare('SELECT COUNT(*) AS c FROM mesures').get().c;
    node.status({ fill: 'green', shape: 'dot', text: n + ' mesures — ' + capteur + ' ' + p.temperature + '°C' });
} catch (e) {
    node.error('insertion SQLite : ' + e.message, msg);
    node.status({ fill: 'red', shape: 'dot', text: e.message });
}
return null;

initialize:
// Ouvre la base une fois au demarrage du flow. SQLite natif de Node 24
// (expose via functionGlobalContext dans settings.js) : zero dependance npm.
const { DatabaseSync } = global.get('sqlite');
const db = new DatabaseSync('/data/thermo.db');

// WAL : lectures concurrentes possibles pendant une ecriture, et moins
// d'ecritures sur la carte SD que le mode rollback par defaut.
db.exec('PRAGMA journal_mode = WAL');
db.exec('PRAGMA synchronous = NORMAL');

// La cle primaire (ts, capteur) rend l'insertion idempotente : rejouer un
// message MQTT retained ne cree pas de doublon.
db.exec(`CREATE TABLE IF NOT EXISTS mesures (
  ts       INTEGER NOT NULL,
  capteur  TEXT    NOT NULL,
  temp     REAL,
  hum      REAL,
  batterie INTEGER,
  PRIMARY KEY (ts, capteur)
)`);
db.exec('CREATE INDEX IF NOT EXISTS idx_capteur_ts ON mesures(capteur, ts)');

context.set('db', db);
const n = db.prepare('SELECT COUNT(*) AS c FROM mesures').get().c;
node.status({ fill: 'green', shape: 'ring', text: n + ' mesures en base' });

finalize:
// Ferme proprement au redeploy, sinon le fichier WAL reste verrouille.
const db = context.get('db');
if (db) { try { db.close(); } catch (e) { /* deja fermee */ } }

func:
// Rejoue les 24 dernieres heures depuis SQLite pour que la courbe ne
// reparte pas de zero a chaque redeploy. Ouverture ponctuelle : ce node
// ne tourne qu'au demarrage, inutile de garder une connexion ouverte.
const { DatabaseSync } = global.get('sqlite');
let db;
try {
    db = new DatabaseSync('/data/thermo.db');
    const depuis = Date.now() - 24 * 3600 * 1000;
    const lignes = db.prepare(
        'SELECT ts, capteur, temp FROM mesures WHERE ts >= ? AND temp IS NOT NULL ORDER BY ts'
    ).all(depuis);

    if (!lignes.length) {
        node.status({ fill: 'grey', shape: 'ring', text: 'aucun historique sur 24 h' });
        return null;
    }

    msg.payload = lignes.map(l => ({ ts: Number(l.ts), temp: l.temp, capteur: l.capteur }));
    msg.action = 'replace';   // remplace le contenu du graphe au lieu de s'y ajouter
    node.status({ fill: 'green', shape: 'dot', text: lignes.length + ' points rechargés' });
    return msg;
} catch (e) {
    node.error('lecture historique : ' + e.message);
    node.status({ fill: 'red', shape: 'dot', text: e.message });
    return null;
} finally {
    if (db) { try { db.close(); } catch (e) { /* ignore */ } }
}

// Resume parle destine a Siri : valeur actuelle + min/max 24 h + comparaison
// avec hier a la meme heure. Toutes les parties sont optionnelles : au debut il
// n'y a qu'une mesure en base, la phrase se reduit d'elle-meme.
const { DatabaseSync } = global.get('sqlite');

const capteur = (msg.req && msg.req.query && msg.req.query.capteur) || 'Chambre';
const LIEUX = { 'Chambre': "dans la chambre", 'Exterieur': 'dehors', 'Extérieur': 'dehors' };
const lieu = LIEUX[capteur] || ('pour ' + capteur);

const repondre = (t) => {
    msg.payload = t;
    msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
    return msg;
};
// Accord singulier/pluriel : "1 degre de plus", "2 degres de plus".
const degres = (v) => Math.abs(v) < 2 ? v + ' degré' : v + ' degrés';

let db;
try {
    db = new DatabaseSync('/data/thermo.db');

    const der = db.prepare(
        'SELECT ts, temp, hum FROM mesures WHERE capteur = ? ORDER BY ts DESC LIMIT 1'
    ).get(capteur);
    if (!der) return repondre("Je n'ai pas encore de mesure " + lieu + '.');

    const maintenant = Date.now();
    let phrase = 'Il fait ' + der.temp + ' degrés ' + lieu;
    if (der.hum !== null) phrase += ', avec ' + Math.round(der.hum) + " pour cent d'humidité";
    phrase += '.';

    // Min/max sur 24 h — seulement si on a de quoi faire une fourchette.
    const bornes = db.prepare(
        'SELECT MIN(temp) AS mn, MAX(temp) AS mx, COUNT(*) AS n FROM mesures WHERE capteur = ? AND ts >= ?'
    ).get(capteur, maintenant - 24 * 3600 * 1000);
    if (bornes && bornes.n > 2 && bornes.mx > bornes.mn) {
        phrase += ' Sur les dernières 24 heures, entre ' + bornes.mn + ' et ' + bornes.mx + ' degrés.';
    }

    // Hier a la meme heure : mesure la plus proche de T-24 h, tolerance +/- 1 h.
    const cible = maintenant - 24 * 3600 * 1000;
    const hier = db.prepare(
        'SELECT temp FROM mesures WHERE capteur = ? AND ts BETWEEN ? AND ? ORDER BY ABS(ts - ?) LIMIT 1'
    ).get(capteur, cible - 3600 * 1000, cible + 3600 * 1000, cible);
    if (hier) {
        const ecart = Math.round((der.temp - hier.temp) * 10) / 10;
        if (Math.abs(ecart) < 0.2) phrase += " C'est autant qu'hier à la même heure.";
        else phrase += " C'est " + degres(Math.abs(ecart)) + (ecart > 0 ? ' de plus' : ' de moins') + " qu'hier à la même heure.";
    }

    // Prevenir si la mesure est vieille : le capteur est peut-etre muet.
    const ageMin = Math.round((maintenant - Number(der.ts)) / 60000);
    if (ageMin > 150) {
        phrase += ' Attention, cette mesure date de ' + Math.round(ageMin / 60) + ' heures.';
    }

    return repondre(phrase);
} catch (e) {
    node.error('resume : ' + e.message);
    return repondre('Je ne peux pas lire l\'historique pour le moment.');
} finally {
    if (db) { try { db.close(); } catch (e) { /* ignore */ } }
}

// Faut-il ouvrir la fenetre de la chambre ? Compare l'exterieur a la
// chambre. Deux usages dans le meme node : le flux MQTT (sortie 1 = notif ntfy,
// uniquement si l'etat change) et une requete HTTP (sortie 2 = reponse parlee).

// Zone morte de 1,5 C entre les deux bascules : les capteurs sont coherents a
// +/-0,3 C, sans hysteresis on basculerait sans arret autour de l'egalite.
const MARGE_OUVRIR = 1.0;   // dehors doit etre 1 C plus frais pour dire "ouvre"
const MARGE_FERMER = 0.5;   // et 0,5 C plus chaud pour dire "ferme"
const FRAICHEUR = 60 * 60 * 1000;   // au-dela, la mesure n'est plus fiable

const estRequete = !!msg.req;
const { DatabaseSync } = global.get('sqlite');
const un = (v) => Math.abs(v) < 2 ? v + ' degré' : v + ' degrés';

let db;
try {
    db = new DatabaseSync('/data/thermo.db');
    const lire = (c) => db.prepare(
        'SELECT ts, temp FROM mesures WHERE capteur = ? AND temp IS NOT NULL ORDER BY ts DESC LIMIT 1'
    ).get(c);
    const ext = lire('Extérieur');
    const ch  = lire('Chambre');

    // Sans les deux mesures, ou avec une mesure perimee, on ne decide rien :
    // mieux vaut se taire que conseiller d'apres une valeur morte.
    const maintenant = Date.now();
    const perime = (m) => !m || (maintenant - Number(m.ts)) > FRAICHEUR;
    if (perime(ext) || perime(ch)) {
        if (!estRequete) return [null, null];
        msg.payload = "Je n'ai pas de mesure assez récente pour comparer l'extérieur et la chambre.";
        msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
        return [null, msg];
    }

    const delta = Math.round((ext.temp - ch.temp) * 10) / 10;   // negatif = plus frais dehors
    const ecart = Math.abs(delta);

    let etat = flow.get('fenetre') || null;   // dernier etat NOTIFIE
    let nouveau = etat;
    if (delta <= -MARGE_OUVRIR) nouveau = 'ouvrir';
    else if (delta >= MARGE_FERMER) nouveau = 'fermer';
    // Entre les deux : zone morte, on conserve l'etat courant.

    const phrases = {
        ouvrir: 'Il fait ' + ext.temp + ' degrés dehors, ' + un(ecart) + " de moins que dans la chambre ("
                + ch.temp + '). Tu peux ouvrir la fenêtre.',
        fermer: 'Il fait ' + ext.temp + ' degrés dehors, ' + un(ecart) + " de plus que dans la chambre ("
                + ch.temp + '). Mieux vaut fermer la fenêtre.',
        neutre: 'Il fait ' + ext.temp + ' degrés dehors et ' + ch.temp + " dans la chambre : "
                + "l'écart est trop faible pour que ça vaille la peine."
    };

    // --- Requete HTTP : on repond l'etat, sans jamais notifier ---
    if (estRequete) {
        msg.payload = phrases[nouveau] || phrases.neutre;
        msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
        return [null, msg];
    }

    // --- Flux MQTT : notifier UNE SEULE FOIS, au changement d'etat ---
    if (!nouveau || nouveau === etat) {
        node.status({ fill: 'grey', shape: 'ring', text: (nouveau || 'neutre') + ' (delta ' + delta + ')' });
        return [null, null];
    }

    flow.set('fenetre', nouveau);
    node.status({ fill: 'green', shape: 'dot', text: 'notifié : ' + nouveau });
    return [{
        payload: phrases[nouveau],
        headers: {
            Title: nouveau === 'ouvrir' ? "Ouvre la fenêtre" : "Ferme la fenêtre",
            Priority: 'default',
            Tags: nouveau === 'ouvrir' ? 'baby,arrow_down' : 'baby,arrow_up'
        }
    }, null];
} catch (e) {
    node.error('fenêtre : ' + e.message);
    return [null, null];
} finally {
    if (db) { try { db.close(); } catch (e) { /* ignore */ } }
}

// Open-Meteo : gratuit, sans cle, et pour la France il s'appuie sur AROME
// (Meteo-France). Les codes meteo suivent la nomenclature WMO 4677.
var d = msg.payload;
if (!d || !d.current) return null;

var CIEL = {
    0:  ['Ciel dégagé', '☀️'],          1:  ['Plutôt dégagé', '🌤️'],
    2:  ['Partiellement nuageux', '⛅'], 3:  ['Couvert', '☁️'],
    45: ['Brouillard', '🌫️'],           48: ['Brouillard givrant', '🌫️'],
    51: ['Bruine légère', '🌦️'],        53: ['Bruine', '🌦️'],
    55: ['Bruine dense', '🌦️'],         56: ['Bruine verglaçante', '🌧️'],
    57: ['Bruine verglaçante dense', '🌧️'],
    61: ['Pluie faible', '🌧️'],         63: ['Pluie', '🌧️'],
    65: ['Pluie forte', '🌧️'],          66: ['Pluie verglaçante', '🌧️'],
    67: ['Pluie verglaçante forte', '🌧️'],
    71: ['Neige faible', '🌨️'],         73: ['Neige', '🌨️'],
    75: ['Neige forte', '🌨️'],          77: ['Grains de neige', '🌨️'],
    80: ['Averses faibles', '🌦️'],      81: ['Averses', '🌦️'],
    82: ['Averses violentes', '⛈️'],     85: ['Averses de neige', '🌨️'],
    86: ['Averses de neige fortes', '🌨️'],
    95: ['Orage', '⛈️'],                96: ['Orage et grêle', '⛈️'],
    99: ['Orage et forte grêle', '⛈️']
};

var c = d.current;
var j = d.daily || {};
var ciel = CIEL[c.weather_code] || ['Code ' + c.weather_code, '❔'];

var JOURS = ['dim', 'lun', 'mar', 'mer', 'jeu', 'ven', 'sam'];

// Midi pour se placer au milieu de la journee : evite qu'un decalage de fuseau
// ne fasse basculer le nom du jour.
function nomDuJour (iso) {
    return JOURS[new Date(iso + 'T12:00:00').getDay()] + ' ' + iso.slice(8, 10) + '/' + iso.slice(5, 7);
}

var jours = (j.time || []).map(function (t, i) {
    var cj = CIEL[j.weather_code[i]] || ['Code ' + j.weather_code[i], '❔'];
    return {
        jour:  nomDuJour(t),
        auj:   i === 0,
        ciel:  cj[0],
        icone: cj[1],
        mini:  j.temperature_2m_min[i],
        maxi:  j.temperature_2m_max[i],
        cumul: j.precipitation_sum[i]
    };
});

var hh = d.hourly || {};
// forecast_hours part de l'heure courante, donc aucun filtrage a faire ici.
var heures = (hh.time || []).map(function (t, i) {
    return {
        heure: t.slice(11, 13) + 'h',
        icone: (CIEL[hh.weather_code[i]] || ['', '\u2754'])[1],
        temp:  hh.temperature_2m[i],
        pluie: hh.precipitation_probability[i],
        mm:    hh.precipitation[i]
    };
});

// Une sortie par carte : la table WMO ci-dessus n'existe qu'ici.
return [
    { payload: {                                            // 1. carte du jour
        temp:     c.temperature_2m,
        ressenti: c.apparent_temperature,
        vent:     Math.round(c.wind_speed_10m),
        ciel:     ciel[0],
        icone:    ciel[1],
        mini:     (j.temperature_2m_min || [])[0],
        maxi:     (j.temperature_2m_max || [])[0],
        pluie:    (j.precipitation_probability_max || [])[0],
        releve:   c.time,
        heures:   heures
    } },
    { payload: jours }                                      // 2. carte previsions 7 jours
];

format:
/* Sur mobile la largeur est la ressource rare. Le dashboard reserve 12 px de
   marge de page et 16 px de chaque cote dans les cartes : on resserre pour
   rendre cette place au contenu. */
@media (max-width: 600px) {
  .nrdb-layout--grid.nrdb-ui-page { padding: 8px !important; }
  .nrdb-ui-group .v-card-text { padding: 0 8px 8px !important; }
}

/* Des que les cartes de capteurs partagent leur ligne, elles ne font plus que
   ~390 px (2 par ligne a 700 px, 4 par ligne a 1300 px) : le gros chiffre et
   les metriques ne tiennent plus cote a cote a leur taille pleine. Le seuil est
   a 600 px et non 700 pour eviter une bande de largeurs ou les cartes seraient
   compactes alors qu'elles sont encore seules sur leur ligne. */
@media (min-width: 600px) {
  .thermo-card { gap: 10px; padding: 0 2px 2px; }
  .thermo-card .col-temp { font-size: 2.6rem; }
  .thermo-card .col-temp .unit { font-size: 1rem; }
  .thermo-card .metrics { gap: 12px; }
  .thermo-card .metric { font-size: 1.05rem; }
  .thermo-card .ic { font-size: 1.1rem; }
  /* Cet ecart separait la qualite de signal de l'horodatage sur une carte deux
     fois plus large ; ici il pousse l'horodatage hors de la carte. */
  .thermo-card .sig { margin-right: 10px; }
}

/* Les douze creneaux horaires de la carte meteo tiennent sur une ligne entre
   900 et 1300 px, ou la carte occupe toute la page. Ailleurs non : en dessous la
   page est trop etroite, au-dela de 1300 px la carte ne fait plus que la moitie
   de la page (les previsions passent a cote). Dans ces deux cas le dernier
   creneau etait rogne, atteignable au defilement mais invisible. Deux rangees de
   six les mettent au large ; a 1300 px cette hauteur comble en prime le vide que
   laissait la carte meteo a cote des previsions, plus hautes qu'elle.
   Sous 600 px on garde le defilement : au doigt il est naturel. */
@media (min-width: 600px) and (max-width: 899px), (min-width: 1300px) {
  .bandeau { display: grid; grid-template-columns: repeat(6, 1fr); gap: 4px 2px;
             overflow-x: visible; }
  .bandeau .creneau { min-width: 0; }
}

func:
const db = context.get('db');
if (!db) { node.error('base SQLite non ouverte'); return null; }

const p = msg.payload || {};
if (typeof p.apparent_power !== 'number') return null;

// Meme logique d'horodatage que pour les thermometres : la date du COMPTEUR
// (last_seen fourni par Z2M), pas l'heure de reception, sinon un message
// retained rejoue au redemarrage fabrique une fausse mesure.
let ts = Date.parse(p.last_seen);
if (!Number.isFinite(ts)) {
    ts = Date.now();
    node.warn('last_seen absent pour Linky, horodatage a la reception');
}

const papp = p.apparent_power;
const iinst = typeof p.rms_current === 'number' ? p.rms_current : null;
const ptec = typeof p.active_register_tier_delivered === 'string' ? p.active_register_tier_delivered : null;
const hchc = typeof p.current_tier1_summ_delivered === 'number' ? p.current_tier1_summ_delivered : null;
const hchp = typeof p.current_tier2_summ_delivered === 'number' ? p.current_tier2_summ_delivered : null;

// Rafales Z2M (un message par attribut Zigbee recu) : on ignore une mesure
// identique a la precedente si elle date de moins d'une minute.
const precedente = db.prepare(
    'SELECT papp, hchc, hchp FROM linky WHERE ts >= ? ORDER BY ts DESC LIMIT 1'
).get(ts - 60000);
if (precedente && precedente.papp === papp && precedente.hchc === hchc && precedente.hchp === hchp) {
    return null;
}

try {
    db.prepare(
        'INSERT OR REPLACE INTO linky (ts, papp, iinst, ptec, hchc, hchp) VALUES (?, ?, ?, ?, ?, ?)'
    ).run(ts, papp, iinst, ptec, hchc, hchp);
    const n = db.prepare('SELECT COUNT(*) AS c FROM linky').get().c;
    node.status({ fill: 'green', shape: 'dot', text: n + ' mesures — ' + papp + ' VA' });
} catch (e) {
    node.error('insertion SQLite Linky : ' + e.message, msg);
    node.status({ fill: 'red', shape: 'dot', text: e.message });
}
return null;

