// Connexion dediee (le contexte 'db' de fn_db_write n'est pas partage entre
// noeuds function). Meme fichier /data/thermo.db, WAL : les deux noeuds
// peuvent ecrire chacun de leur cote sans se bloquer.
const { DatabaseSync } = global.get('sqlite');
const db = new DatabaseSync('/data/thermo.db');
db.exec('PRAGMA journal_mode = WAL');
db.exec('PRAGMA synchronous = NORMAL');
db.exec(`CREATE TABLE IF NOT EXISTS linky (
  ts    INTEGER PRIMARY KEY,
  papp  REAL,
  iinst REAL,
  ptec  TEXT,
  hchc  REAL,
  hchp  REAL
)`);
context.set('db', db);
const n = db.prepare('SELECT COUNT(*) AS c FROM linky').get().c;
node.status({ fill: 'green', shape: 'ring', text: n + ' mesures Linky en base' });

