// Rejoue les 24 dernieres heures de puissance depuis SQLite pour que la
// courbe ne reparte pas de zero a chaque redeploy (meme principe que le
// rechargement des temperatures).
const { DatabaseSync } = global.get('sqlite');
let db;
try {
    db = new DatabaseSync('/data/thermo.db');
    const depuis = Date.now() - 24 * 3600 * 1000;
    const lignes = db.prepare(
        'SELECT ts, papp FROM linky WHERE ts >= ? AND papp IS NOT NULL ORDER BY ts'
    ).all(depuis);

    if (!lignes.length) {
        node.status({ fill: 'grey', shape: 'ring', text: 'aucun historique Linky sur 24 h' });
        return null;
    }

    msg.payload = lignes.map(l => ({ ts: Number(l.ts), papp: l.papp }));
    msg.action = 'replace';
    node.status({ fill: 'green', shape: 'dot', text: lignes.length + ' points rechargés' });
    return msg;
} catch (e) {
    node.error('lecture historique Linky : ' + e.message);
    node.status({ fill: 'red', shape: 'dot', text: e.message });
    return null;
} finally {
    if (db) { try { db.close(); } catch (e) { /* ignore */ } }
}

// Consommation quotidienne = difference entre le dernier index (HC+HP) connu
// d'un jour et celui de la veille. Les index sont cumulatifs, jamais mesures
// directement en kWh/jour, d'ou le calcul par difference plutot qu'une somme.
const { DatabaseSync } = global.get('sqlite');
let db;
try {
    db = new DatabaseSync('/data/thermo.db');

    // 31 jours d'historique pour pouvoir calculer la difference du 30eme jour
    // demande (besoin de son point de depart, la veille).
    const depuis = Date.now() - 31 * 24 * 3600 * 1000;
    const jours = db.prepare(`
        SELECT strftime('%Y-%m-%d', ts / 1000, 'unixepoch', 'localtime') AS jour,
               MAX(ts) AS dernier_ts
        FROM linky
        WHERE ts >= ? AND hchc IS NOT NULL AND hchp IS NOT NULL
        GROUP BY jour
        ORDER BY jour
    `).all(depuis);

    if (jours.length < 2) {
        node.status({ fill: 'grey', shape: 'ring', text: 'pas assez d\'historique Linky pour les courbes journalieres' });
        return null;
    }

    const parJour = jours.map(j => {
        const row = db.prepare('SELECT hchc, hchp FROM linky WHERE ts = ?').get(j.dernier_ts);
        return { jour: j.jour, index: row.hchc + row.hchp };
    });

    const points = [];
    for (let i = 1; i < parJour.length; i++) {
        const kwh = parJour[i].index - parJour[i - 1].index;
        if (kwh >= 0) points.push({ jour: parJour[i].jour, kwh: Math.round(kwh * 100) / 100 });
    }

    node.status({ fill: 'green', shape: 'dot', text: points.length + ' jours calcules' });
    return [
        { payload: points.slice(-7), action: 'replace' },
        { payload: points.slice(-30), action: 'replace' }
    ];
} catch (e) {
    node.error('calcul conso journaliere Linky : ' + e.message);
    node.status({ fill: 'red', shape: 'dot', text: e.message });
    return null;
} finally {
    if (db) { try { db.close(); } catch (e) { /* ignore */ } }
}
